<script setup lang="ts">
import { computed, ref } from "vue";import{onLoad,onPullDownRefresh}from"@dcloudio/uni-app";import WareState from"@/shared/components/WareState.vue";import WarePhoneLink from"@/shared/components/WarePhoneLink.vue";import{baseManagementApi,type BaseSummary,type BaseSupplier}from"../../api/base-management.api";
const id=ref(0),date=ref(''),summary=ref<BaseSummary>(),rows=ref<BaseSupplier[]>([]),keyword=ref(''),loading=ref(true),error=ref('');const visible=computed(()=>rows.value.filter(x=>!keyword.value.trim()||x.name.includes(keyword.value.trim())));async function load(){loading.value=true;error.value='';try{const d=await baseManagementApi.base(id.value,date.value);summary.value=d.summary;rows.value=d.suppliers}catch(e){error.value=e instanceof Error?e.message:'基地详情加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}function open(x:BaseSupplier){uni.navigateTo({url:`/features/base-management/pages/supplier-stock/index?id=${x.id}&date=${date.value}`})}onLoad(q=>{id.value=Number(q?.id);date.value=String(q?.date||new Date().toISOString().slice(0,10));load()});onPullDownRefresh(load)
</script>
<template><view class="page"><WareState v-if="loading" type="loading" title="正在加载基地详情"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><template v-else-if="summary"><view class="title"><b>{{summary.name}}</b><text>{{date}} 场次</text></view><view class="summary"><view><b>{{summary.supplierCount}}</b><text>供应商</text></view><view><b>{{summary.admittedCount}}</b><text>已入场</text></view><view><b>{{summary.productCount}}</b><text>品种</text></view><view><b>{{summary.stockNum}}</b><text>库存/扎</text></view></view><view class="search"><text>⌕</text><input v-model="keyword" placeholder="搜索供应商名称"/></view><view class="section">供应商统计 <text>{{visible.length}}家</text></view><WareState v-if="!visible.length" type="empty" title="暂无供应商数据"/><view v-else class="list"><view v-for="x in visible" :key="x.id" class="card" @click="open(x)"><view class="head"><b>{{x.name}}</b><WarePhoneLink :phone="x.phone" compact /></view><view class="meta"><span>{{x.status===1?'已入场':x.status===0?'未入场':'本场无记录'}}</span><span>{{x.productCount}}种花材</span></view><view class="nums"><text>入场 {{x.inboundNum}}</text><text>已配 {{x.allocatedNum}}</text><strong>库存 {{x.stockNum}}扎</strong></view></view></view></template></view></template>
<style scoped>.page{min-height:100vh;padding:22rpx 24rpx;background:var(--wms-background)}.title{display:flex;align-items:end;justify-content:space-between}.title b{font-size:34rpx}.title text{color:var(--wms-text-secondary);font-size:19rpx}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8rpx;margin:18rpx 0}.summary view{padding:14rpx 4rpx;background:#fff;text-align:center}.summary b,.summary text{display:block}.summary b{color:var(--wms-primary-700);font-size:29rpx}.summary text{font-size:17rpx}.search{display:flex;height:58rpx;align-items:center;gap:8rpx;padding:0 12rpx;background:#fff;border:1rpx solid var(--wms-border);border-radius:10rpx}.search input{flex:1;font-size:19rpx}.section{display:flex;justify-content:space-between;margin:18rpx 2rpx 10rpx;font-size:23rpx;font-weight:700}.section text{color:var(--wms-text-secondary);font-size:18rpx;font-weight:400}.list{display:flex;flex-direction:column;gap:10rpx}.card{padding:18rpx;background:#fff;border-radius:13rpx}.head,.meta,.nums{display:flex;align-items:center;justify-content:space-between}.head b{font-size:23rpx}.meta{margin-top:10rpx;color:var(--wms-text-secondary);font-size:17rpx}.nums{margin-top:13rpx;padding-top:12rpx;border-top:1rpx solid var(--wms-border);font-size:18rpx}.nums strong{color:var(--wms-primary-700)}</style>
<style scoped>.title text,.summary text,.section text{font-size:var(--wms-font-list-caption)}.search input{font-size:var(--wms-font-list-meta)}.head b{font-size:var(--wms-font-list-title)}.meta,.nums{font-size:var(--wms-font-list-meta);line-height:var(--wms-line-list)}</style>
